const solve = (s) => {
  let hasLetter = false;
  let result = "";

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];

    if (/[a-z]/i.test(ch)) {
      hasLetter = true;
      result += ch === ch.toLowerCase() ? ch.toUpperCase() : ch.toLowerCase();
    } else {
      result += ch;
    }
  }

  return hasLetter ? result : [...s].reverse().join("");
};

